import{_ as t,c as s,o as a,ag as o}from"./chunks/framework.B-XtCDNB.js";const u=JSON.parse('{"title":"7. Testing","description":"7. Testing A goal for Vala 1.0 is to have every tests for every documented feature of the language. Tests are located in the tests directory in the repository. There is also a tests directory in the...","frontmatter":{"prev":{"text":"6. Other Tools","link":"/guides/compiler-guide/06-00-other-tools"},"next":{"text":"8. Documentation","link":"/guides/compiler-guide/08-00-documentation"}},"headers":[],"relativePath":"guides/compiler-guide/07-00-testing.md","filePath":"guides/compiler-guide/07-00-testing.md","lastUpdated":1786127789000}'),i={name:"guides/compiler-guide/07-00-testing.md"};function n(d,e,c,r,l,h){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="_7-testing" tabindex="-1">7. Testing <a class="header-anchor" href="#_7-testing" aria-label="Permalink to &quot;7. Testing&quot;">​</a></h1><p>A goal for Vala 1.0 is to have every tests for every documented feature of the language.</p><p>Tests are located in the <code>tests</code> directory in the repository. There is also a <code>tests</code> directory in the <code>valadoc</code> directory for tests specific to the <code>valadoc</code> tool.</p><p>In order to run tests with <code>make check</code> you must have <code>dbus-glib</code> development files installed, otherwise you will get invalid test failures.</p><h2 id="_7-1-what-drives-the-tests" tabindex="-1">7.1. What drives the tests? <a class="header-anchor" href="#_7-1-what-drives-the-tests" aria-label="Permalink to &quot;7.1. What drives the tests?&quot;">​</a></h2><p>Running <code>make check</code> from the top of the repository (or from <code>tests</code> directly) is what drives the suite: it builds <code>valac</code> and then asks automake&#39;s generated test harness to run every file listed in <code>TESTS</code> through <code>testrunner.sh</code>, reporting a summary of passes and failures.</p><p>The top-level <code>Makefile.am</code> also defines a few convenience wrappers around <code>make check</code>:</p><ul><li><code>make test</code> - plain <code>make check</code> in the <code>tests</code> directory.</li><li><code>make test-asan</code> / <code>make test-ubsan</code> - same, but with AddressSanitizer or UndefinedBehaviorSanitizer flags added to <code>TEST_CFLAGS</code>.</li><li><code>make test-update</code> - same, but with <code>UPDATE_EXPECTED=1</code> set, so expected C output files are regenerated rather than checked.</li></ul><h2 id="_7-2-where-is-the-test-suite-defined" tabindex="-1">7.2. Where is the test suite defined? <a class="header-anchor" href="#_7-2-where-is-the-test-suite-defined" aria-label="Permalink to &quot;7.2. Where is the test suite defined?&quot;">​</a></h2><p>The test suite is wired into the autotools build via <code>tests/Makefile.am</code>. Every individual test file is listed under the <code>TESTS</code> variable in that file (and in the <code>Makefile.am</code> of each test subdirectory that has its own, such as <code>tests/girwriter</code>, <code>tests/gtktemplate</code> and <code>tests/fastvapi</code>), so adding a new test means adding its filename to the relevant <code>TESTS</code> list as well as creating the test file itself.</p><p><code>tests/Makefile.am</code> also declares which file extensions are treated as tests and which program is used to run them:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TEST_EXTENSIONS = .vala .gs .gir .test</span></span>
<span class="line"><span></span></span>
<span class="line"><span>TEST_RUNNER = $(abs_top_srcdir)/build-aux/testrunner.sh</span></span>
<span class="line"><span>VALA_LOG_COMPILER = $(TEST_RUNNER)</span></span>
<span class="line"><span>GS_LOG_COMPILER = $(TEST_RUNNER)</span></span>
<span class="line"><span>GIR_LOG_COMPILER = $(TEST_RUNNER)</span></span>
<span class="line"><span>TEST_LOG_COMPILER = $(TEST_RUNNER)</span></span></code></pre></div><p>This uses automake&#39;s parallel test harness: each extension&#39;s <code>*_LOG_COMPILER</code> variable tells automake which program to invoke to &quot;compile and run&quot; a test with that extension, and here all of them point at the same <code>build-aux/testrunner.sh</code> script. <code>AM_TESTS_ENVIRONMENT</code> in the same file exports the environment variables (paths, compiler, flags) that <code>testrunner.sh</code> relies on.</p><h2 id="_7-3-how-do-tests-work" tabindex="-1">7.3. How do tests work? <a class="header-anchor" href="#_7-3-how-do-tests-work" aria-label="Permalink to &quot;7.3. How do tests work?&quot;">​</a></h2><p>The Vala compiler&#39;s tests either compare source file inputs with expected outputs or test for invalid source code (to verify that the compiler is reporting errors correctly). C outputs are also supported.</p><p>Test sources are organised into subdirectories of <code>tests</code> by topic (e.g. <code>basic-types</code>, <code>arrays</code>, <code>dbus</code>, <code>errors</code>, <code>genie</code>), and each test is one of the following file types:</p><ul><li><code>.vala</code> / <code>.gs</code> - A Vala or Genie source file that is expected to compile and run successfully. If a matching <code>.c-expected</code> file exists alongside it, the generated C code is compared against it.</li><li><code>.test</code> - A plain text file containing one or more headers followed by a blank line and then the source code. This format is used for tests that need extra metadata, such as invalid code tests, D-Bus tests, or tests that declare required packages.</li><li><code>.gir</code> - A GIR file used to test <code>vapigen</code>&#39;s VAPI generation; the output is compared against a matching <code>.vapi-expected</code> file.</li></ul><p>A <code>.test</code> file can start with one or more of the following headers:</p><ul><li><code>Packages: &lt;name&gt; ...</code> - Declares the packages to pass to <code>valac</code> via <code>--pkg</code> when compiling the test.</li><li><code>Invalid Code</code> - Marks the test as expected to fail compilation. The test passes only if <code>valac</code> reports an error.</li><li><code>D-Bus</code> - Marks the test as a D-Bus test. The test is compiled and run inside a private D-Bus session via <code>dbus-run-session</code>.</li></ul><p>For example, an invalid code test looks like this:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Invalid Code</span></span>
<span class="line"><span></span></span>
<span class="line"><span>void main () {</span></span>
<span class="line"><span>	try {</span></span>
<span class="line"><span>	} catch (int e) {</span></span>
<span class="line"><span>	}</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="_7-4-how-does-the-test-runner-work" tabindex="-1">7.4. How does the test runner work? <a class="header-anchor" href="#_7-4-how-does-the-test-runner-work" aria-label="Permalink to &quot;7.4. How does the test runner work?&quot;">​</a></h2><p><code>build-aux/testrunner.sh</code> is the script that actually turns a test file into a pass/fail result. For every test file it is given, it:</p><ol><li>Copies the source into a scratch build directory.</li><li>If the file is a <code>.test</code> file, parses its headers (<code>Packages:</code>, <code>Invalid Code</code>, <code>D-Bus</code>, ...) and the source blocks that follow them to figure out what to compile and how (e.g. build two programs for a D-Bus client/server pair).</li><li>Invokes <code>valac</code> (or <code>vapigen</code> for <code>.gir</code> tests) with the flags assembled from the test&#39;s headers, <code>tests-extra-environment.sh</code> (if present), and the environment exported by <code>AM_TESTS_ENVIRONMENT</code>.</li><li>For <code>Invalid Code</code> tests, checks that compilation fails as expected; otherwise it compiles and runs the resulting program, and diffs the generated C code against the matching <code>.c-expected</code> / <code>.h-expected</code> file when one exists.</li></ol><p>Setting <code>UPDATE_EXPECTED=1</code> in the environment makes the runner regenerate the <code>.c-expected</code> files instead of diffing against them, which is how you refresh expected output after an intentional codegen change.</p><h2 id="_7-5-test-environment-configuration" tabindex="-1">7.5. Test environment configuration <a class="header-anchor" href="#_7-5-test-environment-configuration" aria-label="Permalink to &quot;7.5. Test environment configuration&quot;">​</a></h2><p>Any directory under <code>tests</code> may contain a <code>tests-extra-environment.sh</code> file. This is sourced by the test runner before compiling tests in that directory, letting you customise the environment for every test in the directory - for example, by adding extra <code>VALAFLAGS</code>:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">VALAFLAGS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;--vapidir \${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">abs_srcdir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}/girwriter&quot;</span></span></code></pre></div><p>This is useful for things like pointing <code>valac</code> at a directory-local VAPI, or otherwise tweaking compiler flags to exercise specific behaviour without having to repeat the flags in every test.</p>`,29)])])}const g=t(i,[["render",n]]);export{u as __pageData,g as default};
